param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$ValidationRoot='E:/Aliyat/Validation/HibernationAgent',[ValidateRange(1,720)][int]$DurationMinutes=90,[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot 'out/build'};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot);$service=$null;$provider=$null;$checks=0;$cycles=0;$samples=@();$baseline=0
$root=Join-Path $ValidationRoot ('soak-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss'));$runtime=Join-Path $root 'runtime';New-Item -ItemType Directory -Path $runtime -Force|Out-Null
# Copy a frozen build so ongoing development cannot replace a running executable.
Get-ChildItem -LiteralPath $BuildRoot -File|Where-Object {$_.Extension-eq'.dll'-or$_.Name-in@('hibernation-agent.exe','Hibernation_TestProvider.exe')}|ForEach-Object{Copy-Item -LiteralPath $_.FullName -Destination $runtime}
$pluginRoot=Join-Path $runtime 'plugins';New-Item -ItemType Directory -Path $pluginRoot|Out-Null
Get-ChildItem -LiteralPath (Join-Path $BuildRoot 'plugins') -Directory|ForEach-Object{$target=Join-Path $pluginRoot $_.Name;New-Item -ItemType Directory -Path $target|Out-Null;Get-ChildItem -LiteralPath $_.FullName -File|Where-Object {$_.Extension-eq'.dll'-or$_.Name-eq'plugin.json'}|ForEach-Object{Copy-Item -LiteralPath $_.FullName -Destination $target}}
$env:TEMP=$root;$env:TMP=$root;$env:HIBERNATION_SESSION_KEY='soak-session-fixture-only';$headers=@{Authorization='Bearer '+$env:HIBERNATION_SESSION_KEY};$readyPath=Join-Path $root 'ready.json';$configPath=Join-Path $root 'config.json';$providerRoot=Join-Path $root 'provider';New-Item -ItemType Directory -Path $providerRoot|Out-Null
function Check([bool]$Condition,[string]$Name){if(!$Condition){throw "SOAK FAILED: $Name"};$script:checks++}
function Wait-For([scriptblock]$Probe,[string]$Name,[int]$Seconds=25){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 75};throw "SOAK TIMEOUT: $Name"}
function Api([string]$Path,$Data=$null){$a=@{Uri=($script:origin+$Path);Headers=$headers;TimeoutSec=15};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json; charset=utf-8';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))};Invoke-RestMethod @a}
function Idle{Wait-For {!(Api '/api/chat').busy} 'idle'}
function Start-Backend{$script:service=Start-Process -FilePath (Join-Path $runtime 'hibernation-agent.exe') -ArgumentList ('--config "'+$configPath+'" --ready-file "'+$readyPath+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root 'service.log') -RedirectStandardError (Join-Path $root 'error.log');Wait-For {if($script:service.HasExited){throw 'soak backend exited'};if(Test-Path $readyPath){try{return (Get-Content $readyPath -Raw|ConvertFrom-Json).pid-eq$script:service.Id}catch{}};return $false} 'ready';$script:origin='http://127.0.0.1:'+((Get-Content $readyPath -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};$script:service.WaitForExit(15000)|Out-Null;Check $script:service.HasExited 'graceful restart'}
function Plugin([string]$Tool,$Arguments=@{}){$null=Api '/api/plugin/test' @{tool=$Tool;args=$Arguments};Wait-For {$script:pluginResult=Api '/api/plugin/result';return $script:pluginResult.state-in@('succeeded','failed')} $Tool;return $script:pluginResult.result}
try{
 $provider=Start-Process -FilePath (Join-Path $runtime 'Hibernation_TestProvider.exe') -ArgumentList ('"'+$providerRoot+'" 43200') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root 'provider.log') -RedirectStandardError (Join-Path $root 'provider-error.log');Wait-For {Test-Path (Join-Path $providerRoot 'port')} 'fixture';$fixture='http://127.0.0.1:'+([int](Get-Content (Join-Path $providerRoot 'port')))
 $config=Get-Content (Join-Path $ProjectRoot 'config/example.json') -Raw|ConvertFrom-Json -AsHashtable;$config.dataRoot=Join-Path $root 'data';$config.characterRoot=Join-Path $ProjectRoot 'character';$config.uiRoot=Join-Path $ProjectRoot 'ui';$config.pluginRoot=$pluginRoot;$config.profiles=@($config.profiles[0]);$config.maxStartsPerHour=1000;$config.solitudeIntervalMs=3600000;$config.idleBeforeSolitudeMs=0
 $config.plugins=@{television=@{enabled=$true;volume=0};widget=@{enabled=$true;roam=$false};tts=@{enabled=$true;backend='http';origin=$fixture;volume=0;maxSeconds=1;autoSpeak=$false};weather=@{enabled=$true;city='验证城市';geocodingOrigin=$fixture;forecastOrigin=$fixture;refreshMinutes=5}};$config|ConvertTo-Json -Depth 40|Set-Content $configPath -Encoding utf8
 Start-Backend;Copy-Item (Join-Path $providerRoot 'clip.mp4') (Join-Path $config.dataRoot 'materials/clip.mp4');$started=[DateTime]::UtcNow;$finish=$started.AddMinutes($DurationMinutes)
 while([DateTime]::UtcNow-lt$finish){
  $cycleStarted=[DateTime]::UtcNow;Idle;$cycles++;$requestId='soak-'+$cycles;$null=Api '/api/message' @{request_id=$requestId;text=('SOAK_PRIVATE_PAYLOAD_MARKER：第'+$cycles+'次，留下一个未解的问题。')};Idle;$chat=Api '/api/chat';Check ($chat.messages[-1].role-eq'assistant') 'visible reply';Check ($chat.health-eq'ok') 'healthy core'
  if($cycles%3-eq0){$null=Api '/api/solitude' @{};Idle}
  $weather=Plugin 'weather.current';Check ($weather.ok-and$weather.result.weather_code-eq63) 'weather observation'
  $opened=Plugin 'television.open' @{source='clip.mp4';title='Soak synthetic media'};Check $opened.ok 'movie open';Start-Sleep -Milliseconds 160;$null=Plugin 'television.control' @{action='pause'};$null=Plugin 'television.control' @{action='seek';seconds=2};Start-Sleep -Milliseconds 100;$frame=Plugin 'television.observe' @{include_frame=$true};Check ($frame.ok-and$frame.result.image.base64.Length-gt100) 'real frame after seek';$null=Plugin 'television.control' @{action='stop'}
  $voice=Plugin 'speech.speak' @{text='安静的时长检查。';max_seconds=1};Check $voice.ok 'silent WAV output';Start-Sleep -Milliseconds 1150;$voice=Plugin 'speech.status';Check (!$voice.result.active-and$voice.result.last_duration_seconds-lt1.4) 'voice duration'
  $widget=Plugin 'widget.status';Check ($widget.ok-and!$widget.result.desktop) 'headless widget boundary'
  if($cycles%5-eq0){$null=Api '/api/control' @{paused=$true};Check (Api '/api/chat').paused 'pause';Start-Sleep -Milliseconds 200;$null=Api '/api/control' @{paused=$false}}
  if($cycles%10-eq0){$settings=(Api '/api/dashboard').settings|ConvertTo-Json -Depth 40|ConvertFrom-Json -AsHashtable;foreach($id in @('television','widget','tts','weather')){$settings.plugins[$id].enabled=$false};$null=Api '/api/settings' @{settings=$settings};Check (@((Api '/api/dashboard').plugins|Where-Object enabled).Count-eq0) 'plugin unload';foreach($id in @('television','widget','tts','weather')){$settings.plugins[$id].enabled=$true};$null=Api '/api/settings' @{settings=$settings};Check (@((Api '/api/dashboard').plugins|Where-Object enabled).Count-eq4) 'plugin reload'}
  if($cycles%30-eq0){$messages=(Api '/api/chat').messages.Count;Stop-Backend;Start-Backend;Check ((Api '/api/chat').messages.Count-eq$messages) 'dialogue restart continuity'}
  $service.Refresh();$private=$service.PrivateMemorySize64/1MB;if($cycles-eq5){$baseline=$private};Check ($private-lt512) 'absolute memory limit';if($baseline){Check ($private-lt($baseline+128)) 'bounded memory growth'}
  $sample=[pscustomobject]@{cycle=$cycles;minutes=[Math]::Round(([DateTime]::UtcNow-$started).TotalMinutes,2);privateMiB=[Math]::Round($private,2);workingMiB=[Math]::Round($service.WorkingSet64/1MB,2);handles=$service.HandleCount;checks=$checks};$samples+=$sample;$sample|ConvertTo-Json -Compress|Add-Content (Join-Path $root 'progress.jsonl') -Encoding utf8;$sample|ConvertTo-Json -Compress|Write-Output
  $next=$cycleStarted.AddSeconds(60);while([DateTime]::UtcNow-lt$next-and[DateTime]::UtcNow-lt$finish){Start-Sleep -Milliseconds 500}
 }
 Stop-Backend;$database=Join-Path $config.dataRoot 'archive/records.sqlite';Check (![Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($database)).Contains('SOAK_PRIVATE_PAYLOAD_MARKER')) 'archive encrypted after soak';Check (!(Get-Content (Join-Path $root 'service.log') -Raw).Contains('SOAK_PRIVATE_PAYLOAD_MARKER')) 'log excludes content'
 $report=[pscustomobject]@{completed=$true;cycles=$cycles;checks=$checks;durationMinutes=([DateTime]::UtcNow-$started).TotalMinutes;root=$root;samples=$samples;ended=[DateTime]::UtcNow.ToString('O')};$report|ConvertTo-Json -Depth 10|Set-Content (Join-Path $root 'acceptance.json') -Encoding utf8;Write-Output "SOAK PASSED: $cycles cycles, $checks checks. $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
